/* 按名称查询（自动忽略「市/县/区/旗」后缀差异） */
window.__cityPoolFind = function (name) {
  var L = window.__CITY_POOL.list, i;
  for (i = 0; i < L.length; i++) if (L[i][0] === name) return { name: L[i][0], lon: L[i][1], lat: L[i][2], tier: L[i][3], prov: L[i][4] };
  var k = String(name).replace(/[市县区旗]$/, "");
  for (i = 0; i < L.length; i++) if (L[i][0].replace(/[市县区旗]$/, "") === k) return { name: L[i][0], lon: L[i][1], lat: L[i][2], tier: L[i][3], prov: L[i][4] };
  return null;
};

/* 取某一档的全部城市 */
window.__cityPoolByTier = function (t) {
  return window.__CITY_POOL.list.filter(function (c) { return c[3] === t; })
    .map(function (c) { return { name: c[0], lon: c[1], lat: c[2], tier: c[3], prov: c[4] }; });
};

/* 找某个经纬度附近指定公里内的城市（默认 50km），按距离排序 */
window.__cityPoolNear = function (lon, lat, km) {
  km = km || 50;
  var res = [];
  window.__CITY_POOL.list.forEach(function (c) {
    var dy = (c[2] - lat) * 111.32;
    var dx = (c[1] - lon) * 111.32 * Math.cos(lat * Math.PI / 180);
    var d = Math.sqrt(dx * dx + dy * dy);
    if (d <= km) res.push({ name: c[0], lon: c[1], lat: c[2], tier: c[3], prov: c[4], km: +d.toFixed(1) });
  });
  res.sort(function (a, b) { return a.km - b.km; });
  return res;
};